CREATE OR REPLACE FUNCTION public.icash_finish_credit(p_account uuid, p_operation text, p_charge bigint, p_evidence text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.icash_credit_reservations; desired text; available bigint; covered bigint;
begin
 if p_charge is null or p_charge<0 or p_evidence is null or trim(p_evidence)='' then raise exception 'Invalid settlement'; end if;
 select balance_cents into available from public.icash_wallets where account_id=p_account for update;
 if not found then raise exception 'Wallet missing'; end if;
 select * into r from public.icash_credit_reservations where account_id=p_account and operation_key=p_operation for update;
 if not found then raise exception 'Reservation missing'; end if;
 desired:=case when p_charge=0 then 'released' else 'settled' end;
 if r.status<>'reserved' then
  if r.status=desired and coalesce(r.settled_cents,0)=p_charge then return r.status; end if;
  raise exception 'Settlement conflict';
 end if;
 if p_charge>r.amount_cents then raise exception 'Charge exceeds reservation'; end if;
 -- Concurrent completed work may consume the last credits before this receipt.
 -- Record platform-covered overrun explicitly; never debit below zero or retry a charge.
 covered:=greatest(0,p_charge-available);
 if covered>0 then
  insert into public.icash_usage_coverage(account_id,operation_key,gross_cents,customer_cents,covered_cents,evidence_ref)
  values(p_account,p_operation,p_charge,p_charge-covered,covered,p_evidence);
  insert into public.icash_credit_ledger(account_id,event_key,kind,delta_cents,evidence_ref)
  values(p_account,'usage-coverage:'||p_operation,'grant',covered,'Platform-covered concurrent usage; no customer debt: '||p_evidence);
 end if;
 if p_charge>0 then
  insert into public.icash_credit_ledger(account_id,event_key,kind,delta_cents,evidence_ref)
  values(p_account,'usage:'||p_operation,'usage',-p_charge,p_evidence);
 end if;
 update public.icash_wallets set balance_cents=balance_cents+covered-p_charge,reserved_cents=0 where account_id=p_account;
 update public.icash_credit_reservations set status=desired,settled_cents=case when p_charge>0 then p_charge else null end where id=r.id;
 return desired;
end; $function$

CREATE OR REPLACE FUNCTION public.icash_prospecting_progress(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare b public.icash_prospecting_budgets;remaining bigint;total_remaining bigint;minimum bigint;spent bigint;pending bigint;queued bigint;screened bigint;eligible bigint;attempted bigint;responded bigint;active boolean;paused boolean;
begin
 select * into b from public.icash_prospecting_budgets where account_id=p_account order by id desc limit 1;
 if not found then return null;end if;
 remaining:=public.icash_prospecting_available(p_account);
 total_remaining:=public.icash_prospecting_total_available(p_account);
 select least(search.charge_cents,contacts.charge_cents) into minimum from public.icash_discovery_configs c join public.icash_operation_rates search on search.id=c.rate_id left join public.icash_operation_rates contacts on contacts.id=c.contact_rate_id where c.account_id=p_account;
 select coalesce(sum(charged_cents) filter(where state='settled'),0),coalesce(sum(charge_cap_cents) filter(where state in ('reserved','dispatched')),0) into spent,pending from public.icash_operation_spend where account_id=p_account and prospecting_budget_id=b.id;
 select bot_paused into paused from public.icash_accounts where id=p_account;
 select count(*) filter(where s.state in ('queued','running')),count(*) filter(where s.state='complete'),count(*) filter(where s.state='complete' and s.result->'financialCheck'->>'status'='eligible')
  into queued,screened,eligible from public.icash_screening_jobs s where s.account_id=p_account and s.created_at>=b.created_at and s.state<>'archived';
 select count(*) filter(where o.attempted),count(*) filter(where o.responded and not o.opted_out) into attempted,responded
  from public.icash_opportunity_outcomes o where o.account_id=p_account and o.discovered_at>=b.created_at;
 active:=exists(select 1 from public.icash_automation_tickets where account_id=p_account and kind in ('discovery','contacts','voice_dispatch','seller_opener') and state='consumed' and created_at>now()-interval '2 minutes') or queued>0;
 return jsonb_build_object('budgetId',b.id,'startedAt',b.created_at,'limitCents',b.limit_cents,'pacingHours',12,'dailyPercent',50,'dailyLimitCents',b.limit_cents,'batchHours',1,'hourlyLimitCents',least(b.limit_cents,greatest(500,ceil(b.limit_cents/10.0))),'releasedCents',public.icash_prospecting_released(b.baseline_cents,b.created_at),'spentCents',spent,'pendingCents',pending,'remainingCents',remaining,
  'callsBudgetHeld',(select count(*) from public.icash_voice_jobs where account_id=p_account and state='held' and outcome='prospecting_budget_held' and provider_call_sid is null and conversation_id is null),'queued',queued,'screened',screened,'eligible',eligible,'contacted',attempted,'responded',responded,
  'status',case when paused then 'paused' when not public.icash_membership_work_allowed(p_account) then 'membership_required'
   when remaining<coalesce(minimum,1) and pending>0 then 'settling' when remaining<coalesce(minimum,1) and total_remaining>=coalesce(minimum,1) then 'paced' when remaining<coalesce(minimum,1) then 'budget_reached' when active then 'working'
   when exists(select 1 from public.icash_discovery_configs where account_id=p_account and enabled and auto_enabled and data_rights_until>now()) then 'ready' else 'waiting' end);
end $function$

CREATE OR REPLACE FUNCTION public.icash_rotate_inventory_market(p_account uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;m public.icash_inventory_markets;
begin
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or not c.exhausted or not c.enabled or not c.auto_enabled or c.data_rights_until<=now() then return false;end if;
 if not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents) then return false;end if;
 select * into m from public.icash_inventory_markets where account_id=p_account and eligible_until>now() and next_scan_at<=now() and public.icash_research_zip_known(zip) order by public.icash_opportunity_market_score(p_account,zip) desc,priority,zip for update skip locked limit 1;
 if not found then return false;end if;
 update public.icash_discovery_configs set zip=m.zip,next_page=1,revision=gen_random_uuid(),exhausted=false where account_id=p_account;
 update public.icash_inventory_markets set next_scan_at=now()+interval '30 days' where account_id=p_account and zip=m.zip;
 return true;
end $function$
